#include <queue>
#include <vector>
#include <iostream>

using namespace std;

/*
    You are in a city that consists of n intersections numbered from 0 to n - 1 with
bi-directional roads between some intersections. The inputs are generated such that
you can reach any intersection from any other intersection and that there is at most
one road between any two intersections.

    You are given an integer n and a 2D integer array roads where roads[i] = [ui, vi, timei]
means that there is a road between intersections ui and vi that takes timei minutes to travel.
You want to know in how many ways you can travel from intersection 0 to intersection n - 1
in the shortest amount of time.

    Return the number of ways you can arrive at your destination in the shortest amount
of time. Since the answer may be large, return it modulo 10^9 + 7.
*/

struct Edge
{
    unsigned short node;
    unsigned long long weight;

    Edge(unsigned short _node = 0, unsigned long long _weight = 0ull) :
        node(_node), weight(_weight)
    {}
};

struct comp
{
    bool operator() (const Edge& l, const Edge& r) const
    {
        return l.weight > r.weight;
    }
};

constexpr unsigned long long maxLong {200ull * 1000000001ull};
constexpr unsigned long long mod {1000000007};

int countPaths(int n, vector<vector<int>>& roads)
{
    vector<unsigned long long> dist (n, maxLong);
    vector<unsigned long long> pathCount (n, 0);

    vector<vector<Edge>> adjList (n);

    priority_queue<Edge, vector<Edge>, comp> pq;

    Edge temp;
    unsigned long long tempDist;

    size_t i {};
    size_t size {roads.size()};

    dist[0] = 0ull;
    pq.emplace(0, 0ull);

    pathCount[0] = 1;

    for (; i < size; ++i)
    {
        adjList[roads[i][0]].emplace_back(
            static_cast<short>(roads[i][1]),
            static_cast<unsigned long long>(roads[i][2])
        );

        adjList[roads[i][1]].emplace_back(
            static_cast<short>(roads[i][0]),
            static_cast<unsigned long long>(roads[i][2])
        );
    }

    while (!pq.empty())
    {
        temp = pq.top();
        pq.pop();

        if (temp.weight > dist[temp.node])
        {
            continue;
        }

        i = 0;
        size = adjList[static_cast<size_t>(temp.node)].size();

        for (; i < size; ++i)
        {
            tempDist = dist[temp.node] + adjList[temp.node][i].weight;
            
            if (tempDist < dist[adjList[temp.node][i].node]) 
            {
                dist[adjList[temp.node][i].node] = tempDist;
                pathCount[adjList[temp.node][i].node] = pathCount[temp.node];

                pq.emplace(
                    adjList[temp.node][i].node,
                    tempDist
                );
            }
            else if (tempDist == dist[adjList[temp.node][i].node])
            {
                pathCount[adjList[temp.node][i].node] = (pathCount[adjList[temp.node][i].node] + pathCount[temp.node]) % mod;
            }
        }
    }

    return static_cast<int>(pathCount[n - 1]);
}

